{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://judgmentpack.org/schema/0.2.0-draft/judgment-pack-core.schema.json",
  "title": "Judgment Pack Core",
  "description": "Research-preview structural schema. Conformance does not establish truth, authority, safety, or operational fitness.",
  "$comment": "JPS structural conformance requires uri, date, and date-time format assertions even when a general-purpose validator treats format as annotation-only.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "specVersion",
    "id",
    "version",
    "title",
    "decision",
    "outcomes",
    "rules"
  ],
  "properties": {
    "specVersion": {
      "const": "0.2.0-draft"
    },
    "id": {
      "type": "string",
      "format": "uri",
      "minLength": 1
    },
    "version": {
      "type": "string",
      "pattern": "^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)$"
    },
    "title": {
      "$ref": "#/$defs/nonEmptyString"
    },
    "description": {
      "$ref": "#/$defs/nonEmptyString"
    },
    "decision": {
      "$ref": "#/$defs/decision"
    },
    "applicability": {
      "$ref": "#/$defs/condition"
    },
    "evidenceRequirements": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/evidenceRequirement"
      },
      "uniqueItems": true
    },
    "sources": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/source"
      },
      "uniqueItems": true
    },
    "outcomes": {
      "type": "array",
      "minItems": 2,
      "items": {
        "$ref": "#/$defs/outcome"
      },
      "uniqueItems": true
    },
    "rules": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/$defs/rule"
      },
      "uniqueItems": true
    },
    "exceptions": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/exception"
      },
      "uniqueItems": true
    },
    "fallbackOutcome": {
      "$ref": "#/$defs/localId"
    },
    "escalation": {
      "$ref": "#/$defs/escalation"
    },
    "metadata": {
      "$ref": "#/$defs/metadata"
    },
    "extensions": {
      "$ref": "#/$defs/extensions"
    }
  },
  "$defs": {
    "nonEmptyString": {
      "type": "string",
      "minLength": 1
    },
    "localId": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$"
    },
    "decimalString": {
      "type": "string",
      "pattern": "^-?(?:0|[1-9][0-9]*)(?:\\.[0-9]+)?$"
    },
    "extensions": {
      "type": "object",
      "propertyNames": {
        "pattern": "^(?!org\\.judgmentpack\\.)[a-z][a-z0-9]*(?:\\.[a-z][a-z0-9-]*)+$"
      },
      "additionalProperties": true
    },
    "decision": {
      "type": "object",
      "additionalProperties": false,
      "required": ["intent", "question"],
      "properties": {
        "intent": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "question": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "extensions": {
          "$ref": "#/$defs/extensions"
        }
      }
    },
    "evidenceRequirement": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "description", "required"],
      "properties": {
        "id": {
          "$ref": "#/$defs/localId"
        },
        "description": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "required": {
          "type": "boolean"
        },
        "kind": {
          "enum": ["document", "fact", "measurement", "attestation"]
        },
        "extensions": {
          "$ref": "#/$defs/extensions"
        }
      }
    },
    "source": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "title", "locator"],
      "properties": {
        "id": {
          "$ref": "#/$defs/localId"
        },
        "title": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "publisher": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "publishedAt": {
          "type": "string",
          "format": "date"
        },
        "locator": {
          "type": "object",
          "additionalProperties": false,
          "required": ["kind", "value"],
          "properties": {
            "kind": {
              "enum": ["uri", "repository", "path", "other"]
            },
            "value": {
              "$ref": "#/$defs/nonEmptyString"
            }
          }
        },
        "citation": {
          "type": "object",
          "additionalProperties": false,
          "required": ["location", "excerpt"],
          "properties": {
            "location": {
              "$ref": "#/$defs/nonEmptyString"
            },
            "excerpt": {
              "$ref": "#/$defs/nonEmptyString"
            }
          }
        },
        "rights": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "extensions": {
          "$ref": "#/$defs/extensions"
        }
      }
    },
    "outcome": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "label"],
      "properties": {
        "id": {
          "$ref": "#/$defs/localId"
        },
        "label": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "description": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "extensions": {
          "$ref": "#/$defs/extensions"
        }
      }
    },
    "rule": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "description", "when", "outcome", "onUnknown"],
      "properties": {
        "id": {
          "$ref": "#/$defs/localId"
        },
        "description": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "when": {
          "$ref": "#/$defs/condition"
        },
        "outcome": {
          "$ref": "#/$defs/localId"
        },
        "onUnknown": {
          "enum": ["ignore", "escalate"]
        },
        "evidenceRequirementRefs": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/localId"
          },
          "uniqueItems": true
        },
        "sourceRefs": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/localId"
          },
          "uniqueItems": true
        },
        "rationale": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "extensions": {
          "$ref": "#/$defs/extensions"
        }
      }
    },
    "exception": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "description", "when", "effect", "onUnknown"],
      "properties": {
        "id": {
          "$ref": "#/$defs/localId"
        },
        "description": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "when": {
          "$ref": "#/$defs/condition"
        },
        "effect": {
          "enum": ["suppress-rule", "force-outcome", "escalate"]
        },
        "targetRule": {
          "$ref": "#/$defs/localId"
        },
        "outcome": {
          "$ref": "#/$defs/localId"
        },
        "onUnknown": {
          "enum": ["ignore", "escalate"]
        },
        "sourceRefs": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/localId"
          },
          "uniqueItems": true
        },
        "extensions": {
          "$ref": "#/$defs/extensions"
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "effect": {
                "const": "suppress-rule"
              }
            },
            "required": ["effect"]
          },
          "then": {
            "required": ["targetRule"],
            "not": {
              "required": ["outcome"]
            }
          }
        },
        {
          "if": {
            "properties": {
              "effect": {
                "const": "force-outcome"
              }
            },
            "required": ["effect"]
          },
          "then": {
            "required": ["outcome"],
            "not": {
              "required": ["targetRule"]
            }
          }
        },
        {
          "if": {
            "properties": {
              "effect": {
                "const": "escalate"
              }
            },
            "required": ["effect"]
          },
          "then": {
            "not": {
              "anyOf": [
                { "required": ["outcome"] },
                { "required": ["targetRule"] }
              ]
            }
          }
        }
      ]
    },
    "escalation": {
      "type": "object",
      "additionalProperties": false,
      "required": ["triggers", "target"],
      "properties": {
        "triggers": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "enum": [
              "not-applicable",
              "missing-required-evidence",
              "unknown",
              "conflict",
              "no-match"
            ]
          }
        },
        "target": {
          "type": "object",
          "additionalProperties": false,
          "required": ["kind", "name"],
          "properties": {
            "kind": {
              "enum": ["human-role", "queue", "system"]
            },
            "name": {
              "$ref": "#/$defs/nonEmptyString"
            }
          }
        },
        "message": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "extensions": {
          "$ref": "#/$defs/extensions"
        }
      }
    },
    "metadata": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "authors": {
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/nonEmptyString"
          },
          "uniqueItems": true
        },
        "createdAt": {
          "type": "string",
          "format": "date-time"
        },
        "license": {
          "$ref": "#/$defs/nonEmptyString"
        },
        "requiredExtensions": {
          "type": "array",
          "items": {
            "type": "string",
            "pattern": "^(?!org\\.judgmentpack\\.)[a-z][a-z0-9]*(?:\\.[a-z][a-z0-9-]*)+$"
          },
          "uniqueItems": true
        },
        "reviews": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["reviewer", "reviewedAt", "disposition"],
            "properties": {
              "reviewer": {
                "$ref": "#/$defs/nonEmptyString"
              },
              "reviewedAt": {
                "type": "string",
                "format": "date-time"
              },
              "disposition": {
                "enum": ["approved", "changes-requested", "rejected"]
              },
              "note": {
                "$ref": "#/$defs/nonEmptyString"
              }
            }
          }
        },
        "extensions": {
          "$ref": "#/$defs/extensions"
        }
      }
    },
    "condition": {
      "oneOf": [
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["op", "value"],
          "properties": {
            "op": {
              "const": "literal"
            },
            "value": {
              "type": "boolean"
            }
          }
        },
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["op", "conditions"],
          "properties": {
            "op": {
              "enum": ["all", "any"]
            },
            "conditions": {
              "type": "array",
              "minItems": 1,
              "items": {
                "$ref": "#/$defs/condition"
              }
            }
          }
        },
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["op", "condition"],
          "properties": {
            "op": {
              "const": "not"
            },
            "condition": {
              "$ref": "#/$defs/condition"
            }
          }
        },
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["op", "path", "operator", "value"],
          "properties": {
            "op": {
              "const": "fact"
            },
            "path": {
              "type": "string",
              "pattern": "^(?:/(?:[^~/]|~0|~1)*)*$"
            },
            "operator": {
              "enum": [
                "equals",
                "not-equals",
                "greater-than",
                "greater-than-or-equal",
                "less-than",
                "less-than-or-equal",
                "in"
              ]
            },
            "value": true
          },
          "allOf": [
            {
              "if": {
                "properties": {
                  "operator": {
                    "enum": [
                      "greater-than",
                      "greater-than-or-equal",
                      "less-than",
                      "less-than-or-equal"
                    ]
                  }
                },
                "required": ["operator"]
              },
              "then": {
                "properties": {
                  "value": {
                    "$ref": "#/$defs/decimalString"
                  }
                }
              }
            },
            {
              "if": {
                "properties": {
                  "operator": {
                    "const": "in"
                  }
                },
                "required": ["operator"]
              },
              "then": {
                "properties": {
                  "value": {
                    "type": "array",
                    "minItems": 1
                  }
                }
              }
            }
          ]
        },
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["op", "evidenceRequirement"],
          "properties": {
            "op": {
              "const": "evidence-present"
            },
            "evidenceRequirement": {
              "$ref": "#/$defs/localId"
            }
          }
        }
      ]
    }
  }
}

{
  "specVersion": "0.1.0-draft",
  "id": "https://example.com/judgment-packs/expense-approval",
  "version": "0.1.0",
  "title": "Expense approval",
  "description": "Research example for deciding whether an employee expense may be automatically approved.",
  "decision": {
    "intent": "Determine whether an employee expense may be automatically approved, rejected, or sent to a human reviewer.",
    "question": "What approval path should this expense follow?"
  },
  "applicability": {
    "op": "fact",
    "path": "/expense/type",
    "operator": "equals",
    "value": "employee-expense"
  },
  "evidenceRequirements": [
    {
      "id": "receipt",
      "description": "An itemized receipt for the expense.",
      "required": true,
      "kind": "document"
    },
    {
      "id": "cost-center",
      "description": "A valid cost-center identifier.",
      "required": true,
      "kind": "fact"
    }
  ],
  "sources": [
    {
      "id": "expense-policy",
      "title": "Example expense policy",
      "publisher": "Example Corporation",
      "publishedAt": "2026-01-15",
      "locator": {
        "kind": "uri",
        "value": "https://example.com/policies/expenses"
      },
      "citation": {
        "location": "Section 4 — approval thresholds",
        "excerpt": "Expenses above 5000 require finance review. Prohibited categories must be rejected."
      },
      "rights": "Example content; not an operational policy."
    }
  ],
  "outcomes": [
    {
      "id": "approve",
      "label": "Approve",
      "description": "The evidence and declared rules support automatic approval."
    },
    {
      "id": "manual-review",
      "label": "Manual review",
      "description": "An accountable finance reviewer must decide."
    },
    {
      "id": "reject",
      "label": "Reject",
      "description": "The expense falls in a prohibited category."
    }
  ],
  "rules": [
    {
      "id": "prohibited-category",
      "description": "Reject expenses in a prohibited category.",
      "when": {
        "op": "fact",
        "path": "/expense/category",
        "operator": "in",
        "value": ["personal", "cash-equivalent"]
      },
      "outcome": "reject",
      "onUnknown": "escalate",
      "evidenceRequirementRefs": ["receipt", "cost-center"],
      "sourceRefs": ["expense-policy"],
      "rationale": "The example policy prohibits these categories."
    },
    {
      "id": "large-expense",
      "description": "Send expenses above the declared threshold to finance review.",
      "when": {
        "op": "fact",
        "path": "/expense/amount",
        "operator": "greater-than",
        "value": "5000"
      },
      "outcome": "manual-review",
      "onUnknown": "escalate",
      "evidenceRequirementRefs": ["receipt", "cost-center"],
      "sourceRefs": ["expense-policy"],
      "rationale": "The example policy requires finance review above 5000."
    },
    {
      "id": "ordinary-expense",
      "description": "Approve a supported ordinary expense at or below the threshold.",
      "when": {
        "op": "all",
        "conditions": [
          {
            "op": "fact",
            "path": "/expense/amount",
            "operator": "less-than-or-equal",
            "value": "5000"
          },
          {
            "op": "not",
            "condition": {
              "op": "fact",
              "path": "/expense/category",
              "operator": "in",
              "value": ["personal", "cash-equivalent"]
            }
          },
          {
            "op": "evidence-present",
            "evidenceRequirement": "receipt"
          },
          {
            "op": "evidence-present",
            "evidenceRequirement": "cost-center"
          }
        ]
      },
      "outcome": "approve",
      "onUnknown": "escalate",
      "evidenceRequirementRefs": ["receipt", "cost-center"],
      "sourceRefs": ["expense-policy"],
      "rationale": "Ordinary supported expenses may follow the automatic path."
    }
  ],
  "exceptions": [
    {
      "id": "active-investigation",
      "description": "An expense connected to an active investigation requires human review.",
      "when": {
        "op": "fact",
        "path": "/expense/activeInvestigation",
        "operator": "equals",
        "value": true
      },
      "effect": "force-outcome",
      "outcome": "manual-review",
      "onUnknown": "escalate"
    }
  ],
  "fallbackOutcome": "manual-review",
  "escalation": {
    "triggers": [
      "not-applicable",
      "missing-required-evidence",
      "unknown",
      "conflict",
      "no-match"
    ],
    "target": {
      "kind": "human-role",
      "name": "Finance reviewer"
    },
    "message": "Review the expense, cited policy, missing evidence, and conflicting rules."
  },
  "metadata": {
    "authors": ["Judgment Pack Specification contributors"],
    "createdAt": "2026-07-22T00:00:00Z",
    "license": "Apache-2.0"
  }
}
